    e.preventDefault(); 
    if (!file || !file.header) {
      console.error("No file selected");
      return;
    }
    try {
      if(sampleInfo.genusSpecies == "" || sampleInfo.strain == "" ){
        alert("Vui lòng nhập dữ liệu")
      }else{
        const sample = {
          name: sampleInfo.genusSpecies,
          strain: sampleInfo.strain,
          header: file.header,
          length: file.length,
          createdAt: Date.now() 
        }
        const virulence = await apiGetVirulenceInfo(fileInput);
